好的，我把已改好的代码列出来，你在 WSL 里确认后自己编译打包。

## 黑屏根因（已定位）

1. **硬件 SPI 从未初始化**：`CONFIG_LCD_ILI9341_HARDWARE_SPI` 默认 `y`，驱动直接 `hal_spi_write(SPI1)`，但全仓库没人调 `hal_spi_init(SPI1)` → SPI 时钟/控制器未就绪 → 屏幕全黑  
2. **刷的是旧镜像**（20:03），不含 desk_companion 自启  
3. **rcS 同时拉起 luncher_mini + desk_companion**，两个 LVGL 抢 `/dev/lcd0`

---

## 修改 1：补 SPI1 初始化（核心修复）

文件：`vendor/allwinnertech/chips/r528/drivers/rtos-hal/hal/source/disp2/soc/ili9341_lcd_spi.c`

**a) 头部加 `string.h`**（`memset` 用）：

```c
#include <debug.h>
#include <errno.h>
#include <inttypes.h>
#include <stdbool.h>
#include <string.h>
#include <sys/types.h>
```

**b) `board_lcd_initialize` 整函数改成**：

```c
int board_lcd_initialize(void)
{
#if CONFIG_LCD_ILI9341_HARDWARE_SPI
    /* HARDWARE_SPI 路径直接调用 hal_spi_write，但从未调用过 hal_spi_init，
     * 导致 SPI1 时钟/控制器未就绪，LCD 全程写失败（黑屏）。 */
    hal_spi_master_config_t spi_cfg;
    memset(&spi_cfg, 0, sizeof(spi_cfg));
    spi_cfg.clock_frequency = 40000000;
    spi_cfg.bit_order = HAL_SPI_MASTER_MSB_FIRST;
    spi_cfg.cpha = HAL_SPI_MASTER_CLOCK_PHASE0;
    spi_cfg.cpol = HAL_SPI_MASTER_CLOCK_POLARITY0;
    spi_cfg.slave_port = 0;
    spi_cfg.flash = 0;
    if (hal_spi_init(LCD_SPI_PORT, &spi_cfg) != SPI_MASTER_OK)
    {
        lcderr("ERROR: hal_spi_init(SPI1) failed\n");
        return ENODEV;
    }

    /* SPI1 pinmux 会占用 CS，恢复为 GPIO 以继续用软件片选 */
    hal_gpio_pinmux_set_function(LCD_CS_PIN, 1);
    hal_gpio_set_direction(LCD_CS_PIN, GPIO_DIR_OUTPUT);
    hal_gpio_set_data(LCD_CS_PIN, GPIO_DATA_HIGH);
#endif

    g_lcddev = r528_ili93418b_initialize();
    if (g_lcddev == NULL)
    {
        lcdinfo("Initialize ili9341 lcd driver NULL\n");
        return ENODEV;
    }
    lcd_delay_ms(100);
    hal_gpio_sel_vol_mode(LCD_BACKLIGHT_PIN, POWER_MODE_330);
    hal_gpio_set_driving_level(LCD_BACKLIGHT_PIN, GPIO_DRIVING_LEVEL3);
    hal_gpio_set_direction(LCD_BACKLIGHT_PIN, GPIO_DIRECTION_OUTPUT);
    hal_gpio_set_pull(LCD_BACKLIGHT_PIN, GPIO_PULL_DOWN_DISABLED);
    hal_gpio_set_data(LCD_BACKLIGHT_PIN, 1);
    return OK;
}
```

